const publicRoot=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../../');const persistentRoot=process.env.DATA_DIR||path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../data');const backupDir=process.env.BACKUP_DIR||path.join(persistentRoot,'backups');const productUploadDir=process.env.UPLOAD_DIR||path.join(persistentRoot,'uploads','products');fs.mkdirSync(productUploadDir,{recursive:true});fs.mkdirSync(backupDir,{recursive:true});const productUpload=multer({storage:multer.diskStorage({destination:(_r,_f,cb)=>cb(null,productUploadDir),filename:(_r,f,cb)=>{const ext=({ 'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp'})[f.mimetype]||'.img';cb(null,Date.now()+'-'+crypto.randomBytes(8).toString('hex')+ext)}}),limits:{fileSize:8*1024*1024,files:1},fileFilter:(_r,f,cb)=>['image/jpeg','image/png','image/webp'].includes(f.mimetype)?cb(null,true):cb(new Error('Only JPG, PNG and WEBP images are allowed'))});
let backupRunning=false;
async function createDatabaseBackup(kind='AUTO',createdBy=null){
  if(backupRunning)return null;backupRunning=true;
  try{
    fs.mkdirSync(backupDir,{recursive:true});
    const name=`deva-${kind.toLowerCase()}-${new Date().toISOString().replace(/[:.]/g,'-')}.sqlite`;
    const dest=path.join(backupDir,name);
    await db.backup(dest);
    db.prepare('INSERT INTO backups(file_name,created_by,kind) VALUES(?,?,?)').run(name,createdBy,kind);
    return name;
  }finally{backupRunning=false}
}
function pruneBackups(){
  const days=Math.max(1,Number(process.env.BACKUP_RETENTION_DAYS||30));
  const cutoff=Date.now()-days*86400000;
  if(!fs.existsSync(backupDir))return;
  for(const f of fs.readdirSync(backupDir)){
    if(!f.endsWith('.sqlite'))continue;const full=path.join(backupDir,f);
    try{if(fs.statSync(full).mtimeMs<cutoff)fs.unlinkSync(full)}catch{}
  }
  db.prepare("DELETE FROM backups WHERE created_at < datetime('now', ?)").run(`-${days} days`);
}
function startAutomaticBackups(){
  const hours=Math.max(1,Number(process.env.BACKUP_INTERVAL_HOURS||24));
  const run=async()=>{try{const name=await createDatabaseBackup('AUTO',null);if(name)console.log(`[backup] ${name}`);pruneBackups()}catch(e){console.error('[backup] failed',e.message)}};
  setTimeout(run,60_000).unref();setInterval(run,hours*60*60*1000).unref();
}
startAutomaticBackups();
app.post('/api/admin/login',authLimiter,(req,res)=>{const s=z.object({email:z.string().email().max(254),password:z.string().min(8).max(128),code:z.string().regex(/^\d{6}$/).optional()}).strict().safeParse(req.body);if(!s.success)return res.status(400).json({error:'Invalid input'});const email=s.data.email.toLowerCase();const a=db.prepare('SELECT * FROM admins WHERE email=?').get(email);const now=Math.floor(Date.now()/1000);if(a?.lock_until&&a.lock_until>now){audit(req,'LOGIN_BLOCKED',email,{lockUntil:a.lock_until});securityAlert(req,'ACCOUNT_LOCKED',`Account locked: ${email}`,'HIGH',a.id);return res.status(423).json({error:'Account temporarily locked'});}if(!a||!a.active||!bcrypt.compareSync(s.data.password,a.password_hash)){if(a){const attempts=(a.failed_attempts||0)+1;const lock=attempts>=5?now+15*60:null;db.prepare('UPDATE admins SET failed_attempts=?,lock_until=? WHERE id=?').run(lock?0:attempts,lock,a.id);if(lock)securityAlert(req,'BRUTE_FORCE',`Multiple failed login attempts: ${email}`,'HIGH',a.id);}audit(req,'LOGIN_FAILED',email);return res.status(401).json({error:'Invalid credentials'});}if(a.totp_enabled){if(!s.data.code)return res.status(202).json({requires2fa:true});if(!verifyTotp(a.totp_secret,s.data.code)){audit(req,'TWO_FACTOR_FAILED',email);securityAlert(req,'TWO_FACTOR_FAILED',`Invalid 2FA code: ${email}`,'HIGH',a.id);return res.status(401).json({error:'Invalid authentication code'});}}db.prepare('UPDATE admins SET failed_attempts=0,lock_until=NULL,last_login_at=CURRENT_TIMESTAMP WHERE id=?').run(a.id);req.admin={sub:a.id,email:a.email,role:a.role};audit(req,'LOGIN');const session=signAdmin(a);setSessionCookie(res,session.token);res.json({csrfToken:session.csrf,sessionToken:session.token,admin:{id:a.id,email:a.email,role:a.role}})});
