app.get('/api/admin/analytics',requireAdmin,allowPermission('orders.read'),(req,res)=>{const days=Math.min(90,Math.max(7,Number(req.query.days)||30));const modifier=`-${days-1} days`;const visits=db.prepare("SELECT count(*) n FROM visitor_events WHERE event_type='page_view' AND created_at>=datetime('now',?)").get(modifier).n;const uniqueVisitors=db.prepare("SELECT count(DISTINCT session_id) n FROM visitor_events WHERE created_at>=datetime('now',?)").get(modifier).n;const todayVisits=db.prepare("SELECT count(*) n FROM visitor_events WHERE event_type='page_view' AND date(created_at)=date('now')").get().n;const todayVisitors=db.prepare("SELECT count(DISTINCT session_id) n FROM visitor_events WHERE date(created_at)=date('now')").get().n;const sales=db.prepare("SELECT count(*) n,COALESCE(sum(total_usd),0) usd,COALESCE(sum(total_iqd),0) iqd FROM orders WHERE created_at>=datetime('now',?) AND (payment_status='PAID' OR status IN ('PAID','DELIVERED'))").get(modifier);const pending=db.prepare("SELECT count(*) n FROM orders WHERE status='PENDING'").get().n;const daily=db.prepare(`WITH RECURSIVE dates(d) AS (SELECT date('now', ?) UNION ALL SELECT date(d,'+1 day') FROM dates WHERE d<date('now')) SELECT d date,(SELECT count(*) FROM visitor_events v WHERE v.event_type='page_view' AND date(v.created_at)=d) visits,(SELECT count(*) FROM orders o WHERE date(o.created_at)=d) orders,(SELECT COALESCE(sum(o.total_usd),0) FROM orders o WHERE date(o.created_at)=d AND (o.payment_status='PAID' OR o.status IN ('PAID','DELIVERED'))) revenue_usd FROM dates`).all(modifier);const topPages=db.prepare("SELECT path,count(*) views,count(DISTINCT session_id) visitors FROM visitor_events WHERE event_type='page_view' AND created_at>=datetime('now',?) GROUP BY path ORDER BY views DESC LIMIT 8").all(modifier);const topProducts=db.prepare("SELECT product_id,count(*) views FROM visitor_events WHERE event_type='product_view' AND product_id IS NOT NULL AND created_at>=datetime('now',?) GROUP BY product_id ORDER BY views DESC LIMIT 8").all(modifier);res.json({days,summary:{visits,uniqueVisitors,todayVisits,todayVisitors,salesCount:sales.n,revenueUsd:Number(sales.usd||0),revenueIqd:Number(sales.iqd||0),pendingOrders:pending},daily,topPages,topProducts})});
