// ---- DEVA Rewards Club / Friday Gifts ----
const rewardsPhone=v=>String(v||'').replace(/[^0-9+]/g,'').replace(/^00964/,'+964').replace(/^964/,'+964');
const rewardToken=()=>String(process.env.REWARDS_QR_TOKEN||'');
const safeTokenEqual=(a,b)=>{a=String(a||'');b=String(b||'');if(!a||!b||a.length!==b.length)return false;return crypto.timingSafeEqual(Buffer.from(a),Buffer.from(b))};
function rewardConfig(){return db.prepare('SELECT * FROM rewards_settings WHERE id=1').get()}
function baghdadParts(d=new Date()){const x=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',weekday:'short',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return x}
function weeklyDrawKey(d=new Date()){const x=baghdadParts(d);return `${x.year}-${x.month}-${x.day}`}
function weightedPrize(grand=false){const rows=db.prepare('SELECT * FROM rewards_prizes WHERE active=1 AND is_grand=? ORDER BY id').all(grand?1:0);if(!rows.length)return null;const total=rows.reduce((n,x)=>n+Math.max(1,Number(x.weight)||1),0);let r=crypto.randomInt(total);for(const x of rows){r-=Math.max(1,Number(x.weight)||1);if(r<0)return x}return rows[0]}
function shouldGrandDraw(){const cfg=rewardConfig();const last=db.prepare('SELECT drawn_at FROM rewards_draws WHERE is_grand=1 ORDER BY id DESC LIMIT 1').get();if(last)return Date.now()-new Date(last.drawn_at+'Z').getTime()>=90*86400000;const milestone=db.prepare('SELECT joined_at FROM rewards_members WHERE active=1 ORDER BY joined_at,id LIMIT 1 OFFSET ?').get(Math.max(0,Number(cfg.target_members||1000)-1));if(!milestone)return false;return Date.now()-new Date(milestone.joined_at+'Z').getTime()>=90*86400000}
function performRewardDraw({grand=false,key=null,actor='SYSTEM'}={}){
  const cfg=rewardConfig();const n=db.prepare('SELECT count(*) n FROM rewards_members WHERE active=1').get().n;
  if(!cfg.enabled)throw new Error('Rewards are disabled');if(n<cfg.target_members)throw new Error(`Need ${cfg.target_members-n} more members`);
  const drawKey=key||weeklyDrawKey();const exists=db.prepare('SELECT id FROM rewards_draws WHERE draw_key=? AND is_grand=?').get(drawKey,grand?1:0);if(exists)throw new Error('Draw already completed');
  const members=db.prepare('SELECT id,customer_name,phone FROM rewards_members WHERE active=1 ORDER BY id').all();const winner=members[crypto.randomInt(members.length)];const prize=weightedPrize(grand);if(!prize)throw new Error('No active prize configured');
  const code=`DEVA-${grand?'SUPER':'FRI'}-${crypto.randomBytes(4).toString('hex').toUpperCase()}`;const expiry=prize.type==='PRODUCT'?null:new Date(Date.now()+Number(cfg.credit_expiry_days||30)*86400000).toISOString();
  const proof=crypto.createHash('sha256').update(`${drawKey}|${grand?1:0}|${winner.id}|${prize.id}|${code}|${members.length}|${process.env.JWT_SECRET}`).digest('hex');
  const info=db.prepare('INSERT INTO rewards_draws(draw_key,member_id,prize_id,is_grand,participant_count,redeem_code,expires_at,proof_hash) VALUES(?,?,?,?,?,?,?,?)').run(drawKey,winner.id,prize.id,grand?1:0,members.length,code,expiry,proof);
  db.prepare('UPDATE rewards_members SET wins_count=wins_count+1,last_seen_at=CURRENT_TIMESTAMP WHERE id=?').run(winner.id);
  return {id:info.lastInsertRowid,winner,prize,redeemCode:code,proofHash:proof,participantCount:members.length,grand};
}
function maybeRunFridayRewards(){try{const cfg=rewardConfig();if(!cfg?.enabled)return;const p=baghdadParts();if(p.weekday!=='Fri'||Number(p.hour)<Number(cfg.friday_hour||21))return;const key=weeklyDrawKey();if(!db.prepare('SELECT 1 FROM rewards_draws WHERE draw_key=? AND is_grand=0').get(key)){try{performRewardDraw({grand:false,key})}catch(e){console.log('[rewards weekly]',e.message)}}if(shouldGrandDraw()&&!db.prepare('SELECT 1 FROM rewards_draws WHERE draw_key=? AND is_grand=1').get(key)){try{performRewardDraw({grand:true,key})}catch(e){console.log('[rewards grand]',e.message)}}}catch(e){console.error('[rewards scheduler]',e.message)}}
setTimeout(maybeRunFridayRewards,15_000).unref();setInterval(maybeRunFridayRewards,60_000).unref();

// Live DEVA Draw Room presence (ephemeral; no personal data stored)
const rewardPresence=new Map();
function pruneRewardPresence(){const cut=Date.now()-45000;for(const [k,v] of rewardPresence)if(v.lastSeen<cut)rewardPresence.delete(k)}
function rewardPresenceStats(){pruneRewardPresence();let rewards=0,waiting=0;for(const v of rewardPresence.values()){if(v.area==='REWARDS')rewards++;if(v.waiting)waiting++}return {onlineNow:rewardPresence.size,inRewardsNow:rewards,waitingForDraw:waiting}}
app.post('/api/rewards/presence',(req,res)=>{const v=z.object({sessionId:z.string().min(8).max(80),area:z.enum(['APP','REWARDS']).default('APP'),waiting:z.boolean().default(false)}).safeParse(req.body||{});if(!v.success)return res.status(400).json({error:'Invalid presence'});rewardPresence.set(v.data.sessionId,{...v.data,lastSeen:Date.now()});res.status(202).json({ok:true})});
app.get('/api/rewards/live',(req,res)=>res.json(rewardPresenceStats()));
