app.post('/api/rewards/activate',authLimiter,(req,res)=>{const v=z.object({customer_name:z.string().trim().min(2).max(100),phone:z.string().trim().min(7).max(25),email:z.string().email().optional().or(z.literal('')),token:z.string().min(8).max(500),consent:z.literal(true)}).strict().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid member data'});const expected=rewardToken();if(expected.length<24)return res.status(503).json({error:'Rewards QR is not configured'});if(!safeTokenEqual(v.data.token,expected))return res.status(403).json({error:'Invalid DEVA showroom QR'});const phone=rewardsPhone(v.data.phone);const row=db.prepare('SELECT id FROM rewards_members WHERE phone=?').get(phone);if(row){db.prepare('UPDATE rewards_members SET customer_name=?,email=?,active=1,last_seen_at=CURRENT_TIMESTAMP WHERE id=?').run(v.data.customer_name,v.data.email||null,row.id);return res.json({ok:true,alreadyMember:true})}const info=db.prepare('INSERT INTO rewards_members(customer_name,phone,email,consent) VALUES(?,?,?,1)').run(v.data.customer_name,phone,v.data.email||null);res.status(201).json({ok:true,memberId:info.lastInsertRowid})});
app.get('/api/admin/rewards',requireAdmin,allowPermission('rewards.manage'),(req,res)=>{const cfg=rewardConfig(),count=db.prepare('SELECT count(*) n FROM rewards_members WHERE active=1').get().n;const members=db.prepare('SELECT id,customer_name,phone,email,joined_at,wins_count,active FROM rewards_members ORDER BY id DESC LIMIT 5000').all();const prizes=db.prepare('SELECT * FROM rewards_prizes ORDER BY is_grand,id').all();const draws=db.prepare("SELECT d.*,m.customer_name,m.phone,p.label prize_label,p.type prize_type,p.value prize_value FROM rewards_draws d JOIN rewards_members m ON m.id=d.member_id JOIN rewards_prizes p ON p.id=d.prize_id ORDER BY d.id DESC LIMIT 200").all();res.json({config:cfg,memberCount:count,members,prizes,draws})});
app.patch('/api/admin/rewards/settings',requireAdmin,requireCsrf,allowPermission('rewards.manage'),(req,res)=>{const v=z.object({target_members:z.number().int().min(1).max(1000000).optional(),enabled:z.boolean().optional(),friday_hour:z.number().int().min(0).max(23).optional(),credit_expiry_days:z.number().int().min(1).max(365).optional()}).strict().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid settings'});const old=rewardConfig(),x={...old,...v.data};db.prepare('UPDATE rewards_settings SET target_members=?,enabled=?,friday_hour=?,credit_expiry_days=?,updated_at=CURRENT_TIMESTAMP WHERE id=1').run(x.target_members,x.enabled?1:0,x.friday_hour,x.credit_expiry_days);audit(req,'REWARDS_SETTINGS_UPDATED','1',v.data);res.json({ok:true})});
app.patch('/api/admin/rewards/prizes/:id',requireAdmin,requireCsrf,allowPermission('rewards.manage'),(req,res)=>{const id=Number(req.params.id),old=db.prepare('SELECT * FROM rewards_prizes WHERE id=?').get(id);if(!old)return res.status(404).json({error:'Prize not found'});const v=z.object({label:z.string().min(2).max(120).optional(),value:z.number().nonnegative().optional(),min_purchase_usd:z.number().nonnegative().optional(),weight:z.number().int().min(1).max(10000).optional(),active:z.boolean().optional()}).strict().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid prize'});const x={...old,...v.data};db.prepare('UPDATE rewards_prizes SET label=?,value=?,min_purchase_usd=?,weight=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(x.label,x.value,x.min_purchase_usd,x.weight,x.active?1:0,id);audit(req,'REWARD_PRIZE_UPDATED',String(id),v.data);res.json({ok:true})});
app.post('/api/admin/rewards/draw',requireAdmin,requireCsrf,sensitiveLimiter,allowPermission('rewards.manage'),(req,res)=>{const v=z.object({grand:z.boolean().optional().default(false)}).safeParse(req.body||{});if(!v.success)return res.status(400).json({error:'Invalid draw'});try{const result=performRewardDraw({grand:v.data.grand,key:`MANUAL-${Date.now()}`,actor:req.admin.email});audit(req,'REWARD_DRAW',String(result.id),{grand:v.data.grand,winner:result.winner.id,prize:result.prize.id,proof:result.proofHash});res.json({ok:true,...result})}catch(e){res.status(409).json({error:e.message})}});
app.post('/api/admin/rewards/draws/:id/redeem',requireAdmin,requireCsrf,allowPermission('rewards.manage'),(req,res)=>{const id=Number(req.params.id);const d=db.prepare("SELECT id,redeem_status FROM rewards_draws WHERE id=?").get(id);if(!d)return res.status(404).json({error:'Draw not found'});if(d.redeem_status==='REDEEMED')return res.status(409).json({error:'Already redeemed'});db.prepare("UPDATE rewards_draws SET redeem_status='REDEEMED',redeemed_at=CURRENT_TIMESTAMP WHERE id=?").run(id);audit(req,'REWARD_REDEEMED',String(id));res.json({ok:true})});
app.get('/api/admin/rewards/qr.svg',requireAdmin,allowPermission('rewards.manage'),async(req,res)=>{const token=rewardToken();if(token.length<24)return res.status(503).send('REWARDS_QR_TOKEN not configured');const base=(process.env.PUBLIC_BASE_URL||`${req.protocol}://${req.get('host')}`).replace(/\/$/,'');const url=`${base}/?deva_reward=${encodeURIComponent(token)}`;const svg=await QRCode.toString(url,{type:'svg',margin:2,width:420,errorCorrectionLevel:'M'});res.type('image/svg+xml').send(svg)});

const nextProductCode=()=>{const row=db.prepare("SELECT max(CAST(product_code AS INTEGER)) n FROM products WHERE product_code GLOB '[0-9]*'").get();return String(Math.max(155,Number(row?.n||155))+1).padStart(4,'0')};
const builtinCatalogById=(()=>{try{const items=JSON.parse(fs.readFileSync(path.join(path.dirname(fileURLToPath(import.meta.url)),'builtin-products.json'),'utf8'));return new Map((Array.isArray(items)?items:[]).map(x=>[String(x.id),x]));}catch(e){console.error('[D25] Failed to load bundled catalog map:',e.message);return new Map();}})();
const builtinCatalog=[...builtinCatalogById.values()];
const builtinByCode=new Map(builtinCatalog.filter(x=>x.code).map(x=>[String(x.code),x]));
const builtinByNameCategory=new Map(builtinCatalog.map(x=>[`${String(x.category||'').toLowerCase()}|${String(x.name||'').trim().toLowerCase()}`,x]));
const moneyValue=v=>{const n=Number(String(v??'').replace(/[^0-9.]/g,''));return Number.isFinite(n)?n:0};
const builtinForRow=row=>{if(!row)return null;return builtinCatalogById.get(String(row.id))||builtinByCode.get(String(row.product_code||''))||builtinByNameCategory.get(`${String(row.category||'').toLowerCase()}|${String(row.name||'').trim().toLowerCase()}`)||null};
const canonicalProductId=id=>{const direct=builtinCatalogById.get(String(id));if(direct)return String(direct.id);const row=db.prepare('SELECT id,name,category,product_code FROM products WHERE id=?').get(String(id));const b=builtinForRow(row);return b?String(b.id):String(id)};

const productTombstoneFor=(idOrCode)=>db.prepare('SELECT product_id,product_code,deleted_at FROM product_tombstones WHERE product_id=? OR product_code=? LIMIT 1').get(String(idOrCode||''),String(idOrCode||''));
const deletedProductIds=()=>db.prepare('SELECT product_id,product_code,deleted_at FROM product_tombstones ORDER BY deleted_at DESC').all();
function purgeDeletedBuiltinRows(){
  const tombstones=deletedProductIds();
  for(const t of tombstones){
    if(t.product_id) db.prepare('DELETE FROM products WHERE id=?').run(String(t.product_id));
    if(t.product_code) db.prepare('DELETE FROM products WHERE product_code=?').run(String(t.product_code));
  }
  return tombstones.length;
}

function repairCatalogDuplicates(context='request'){
  let removed=0,created=0,repaired=0;
  const tx=db.transaction(()=>{
    for(const b of builtinCatalog){
      const code=String(b.code||'');
      if(productTombstoneFor(String(b.id))||productTombstoneFor(code)){
        db.prepare('DELETE FROM products WHERE id=? OR product_code=?').run(String(b.id),code);
        continue;
      }
      const rows=db.prepare(`SELECT * FROM products WHERE id=? OR product_code=? OR (lower(name)=lower(?) AND category=?) ORDER BY CASE WHEN id=? THEN 0 WHEN product_code=? THEN 1 ELSE 2 END, datetime(updated_at) DESC, rowid DESC`).all(String(b.id),code,String(b.name),String(b.category),String(b.id),code);
      let canonical=rows.find(r=>String(r.id)===String(b.id));
      const source=canonical||rows[0]||null;
      if(!canonical){
        db.prepare(`INSERT OR IGNORE INTO products(id,name,category,price_usd,old_price_usd,image,active,stock_qty,low_stock_threshold,product_code,images_json,catalog_origin,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)`).run(
          String(b.id),String(b.name),String(b.category),source?Number(source.price_usd||0):moneyValue(b.price),source?.old_price_usd??(b.oldPrice?moneyValue(b.oldPrice):null),String(b.image||''),source?Number(source.active!==0):1,Number(source?.stock_qty||0),Number(source?.low_stock_threshold??2),code,JSON.stringify(Array.isArray(b.images)?b.images:(b.image?[b.image]:[])),'BUILTIN'
        );
        canonical=db.prepare('SELECT * FROM products WHERE id=?').get(String(b.id));created++;
      }
      db.prepare(`UPDATE products SET name=?,category=?,image=?,product_code=?,images_json=?,catalog_origin='BUILTIN' WHERE id=?`).run(String(b.name),String(b.category),String(b.image||''),code,JSON.stringify(Array.isArray(b.images)?b.images:(b.image?[b.image]:[])),String(b.id));
      repaired++;
      for(const dup of rows){
        if(String(dup.id)===String(b.id))continue;
        try{db.prepare('INSERT OR IGNORE INTO customer_favorites(customer_id,product_id,created_at) SELECT customer_id,?,created_at FROM customer_favorites WHERE product_id=?').run(String(b.id),String(dup.id));db.prepare('DELETE FROM customer_favorites WHERE product_id=?').run(String(dup.id))}catch{}
        try{const carts=db.prepare('SELECT customer_id,qty FROM customer_cart WHERE product_id=?').all(String(dup.id));for(const c of carts){const ex=db.prepare('SELECT qty FROM customer_cart WHERE customer_id=? AND product_id=?').get(c.customer_id,String(b.id));if(ex)db.prepare('UPDATE customer_cart SET qty=?,updated_at=CURRENT_TIMESTAMP WHERE customer_id=? AND product_id=?').run(Math.max(Number(ex.qty||0),Number(c.qty||0)),c.customer_id,String(b.id));else db.prepare('INSERT INTO customer_cart(customer_id,product_id,qty) VALUES(?,?,?)').run(c.customer_id,String(b.id),Number(c.qty||1));}db.prepare('DELETE FROM customer_cart WHERE product_id=?').run(String(dup.id))}catch{}
        db.prepare('DELETE FROM products WHERE id=?').run(String(dup.id));removed++;
      }
    }
  });
  tx();
  if(removed||created)console.log(`[D25] Catalog identity repair (${context}): created=${created}, removedDuplicates=${removed}, repaired=${repaired}`);
  return {created,removed,repaired};
}

const repairBuiltinIdentity=(id)=>{const canonicalId=canonicalProductId(id);const builtin=builtinCatalogById.get(canonicalId);if(!builtin)return null;repairCatalogDuplicates('identity');const row=db.prepare('SELECT id,product_code FROM products WHERE id=?').get(canonicalId);return String(builtin.code||row?.product_code||'')};

// D27: guarantee that a built-in product exists before a price-only update.
// This repairs partial/corrupted SQLite states without touching image/name/category.
function ensureBuiltinProductRow(requestedId){
  const raw=String(requestedId||'');
  let builtin=builtinCatalogById.get(raw)||builtinByCode.get(raw)||null;
  if(!builtin){
    const row=db.prepare('SELECT id,name,category,product_code FROM products WHERE id=?').get(raw);
    builtin=builtinForRow(row);
  }
  if(!builtin)return raw;
  const id=String(builtin.id);
  const tombstone=productTombstoneFor(id)||productTombstoneFor(String(builtin.code||''));
  if(tombstone){const err=new Error('Product was deleted');err.code='PRODUCT_DELETED';throw err;}
  const existing=db.prepare('SELECT * FROM products WHERE id=?').get(id);
  if(!existing){
    db.prepare(`INSERT INTO products(id,name,category,price_usd,old_price_usd,image,active,stock_qty,low_stock_threshold,product_code,images_json,catalog_origin,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)`).run(
      id,String(builtin.name),String(builtin.category),moneyValue(builtin.price),builtin.oldPrice?moneyValue(builtin.oldPrice):null,String(builtin.image||''),1,0,2,String(builtin.code||''),JSON.stringify(Array.isArray(builtin.images)?builtin.images:(builtin.image?[builtin.image]:[])),'BUILTIN'
    );
  }else{
    // Identity fields are canonical; price fields stay exactly as previously edited.
    db.prepare(`UPDATE products SET name=?,category=?,image=?,product_code=?,images_json=?,catalog_origin='BUILTIN' WHERE id=?`).run(
      String(builtin.name),String(builtin.category),String(builtin.image||''),String(builtin.code||existing.product_code||''),JSON.stringify(Array.isArray(builtin.images)?builtin.images:(builtin.image?[builtin.image]:[])),id
    );
  }
  return id;
}

// One-time D27 recovery for older patches that accidentally left built-in products inactive.
try{
  const key='d27_builtin_active_recovery';
  if(!db.prepare('SELECT 1 FROM app_meta WHERE key=?').get(key)){
    syncBuiltinCatalog({onlyWhenEmpty:false});
    for(const b of builtinCatalog){
      if(productTombstoneFor(String(b.id))||productTombstoneFor(String(b.code||'')))continue;
      ensureBuiltinProductRow(String(b.id));
      db.prepare("UPDATE products SET active=1 WHERE id=?").run(String(b.id));
    }
    purgeDeletedBuiltinRows();
    db.prepare(`INSERT INTO app_meta(key,value,updated_at) VALUES(?,?,CURRENT_TIMESTAMP) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=CURRENT_TIMESTAMP`).run(key,String(builtinCatalog.length));
    console.log(`[D27] Recovered ${builtinCatalog.length} built-in products and categories`);
  }
}catch(e){console.error('[D27] built-in active recovery failed:',e.message)}
