app.get('/api/customer/orders',requireCustomer,(req,res)=>res.json(db.prepare('SELECT id,total_usd,total_iqd,status,payment_status,created_at,updated_at FROM orders WHERE customer_id=? ORDER BY created_at DESC LIMIT 100').all(req.customer.id)));
app.post('/api/customer/push-token',requireCustomer,(req,res)=>{const v=z.object({platform:z.enum(['IOS','ANDROID']),token:z.string().min(16).max(4096)}).strict().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid push token'});db.prepare('INSERT INTO customer_push_tokens(customer_id,platform,token,active) VALUES(?,?,?,1) ON CONFLICT(token) DO UPDATE SET customer_id=excluded.customer_id,platform=excluded.platform,active=1,updated_at=CURRENT_TIMESTAMP').run(req.customer.id,v.data.platform,v.data.token);res.json({ok:true});});
app.delete('/api/customer/push-token',requireCustomer,(req,res)=>{const v=z.object({token:z.string().min(16).max(4096)}).strict().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid push token'});db.prepare('UPDATE customer_push_tokens SET active=0,updated_at=CURRENT_TIMESTAMP WHERE customer_id=? AND token=?').run(req.customer.id,v.data.token);res.status(204).end();});
app.post('/api/admin/push/broadcast',requireAdmin,requireCsrf,sensitiveLimiter,async(req,res)=>{const v=z.object({title:z.string().min(1).max(80),body:z.string().min(1).max(240),data:z.record(z.union([z.string(),z.number(),z.boolean()])).optional()}).strict().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid notification'});const tokens=db.prepare('SELECT token FROM customer_push_tokens WHERE active=1').all().map(x=>x.token);try{const out=await sendExpoPush(tokens,v.data);audit(req,'PUSH_BROADCAST','customers',{sent:out.sent,title:v.data.title});res.json({ok:true,sent:out.sent});}catch(e){res.status(502).json({error:e.message})}});

const orderSchema=z.object({customer:z.object({name:z.string().min(2).max(100),phone:z.string().min(7).max(25),email:z.string().email().optional().or(z.literal(''))}),items:z.array(z.object({id:z.string().max(80),name:z.string().max(150),qty:z.number().int().min(1).max(20),priceUsd:z.number().nonnegative()})).min(1).max(50),welcomeDiscount:z.boolean().optional().default(false)});

// ---- Sponsored Ads / DEVA Partners ----
const sponsorAdSchema=z.object({company_name:z.string().min(2).max(100),title:z.string().min(2).max(160),description:z.string().max(700).optional().default(''),image:z.string().max(500).optional().default(''),cta_label:z.string().max(50).optional().default('زیاتر ببینە'),cta_url:z.string().max(700).optional().default(''),whatsapp:z.string().max(40).optional().default(''),placement:z.enum(['HOME','PRODUCTS','PARTNERS']).default('HOME'),start_at:z.string().min(10).max(40),end_at:z.string().min(10).max(40),active:z.boolean().optional().default(true)}).strict().refine(x=>new Date(x.end_at)>new Date(x.start_at),{message:'End must be after start'});
function publicSponsorAd(x){return {id:x.id,company_name:x.company_name,title:x.title,description:x.description,image:x.image,cta_label:x.cta_label,cta_url:x.cta_url,whatsapp:x.whatsapp,placement:x.placement,start_at:x.start_at,end_at:x.end_at}}
app.get('/api/sponsors/active',(req,res)=>{const placement=String(req.query.placement||'HOME').toUpperCase();const allowed=['HOME','PRODUCTS','PARTNERS'];if(!allowed.includes(placement))return res.status(400).json({error:'Invalid placement'});const rows=db.prepare("SELECT * FROM sponsor_ads WHERE active=1 AND placement=? AND datetime(start_at)<=datetime('now') AND datetime(end_at)>=datetime('now') ORDER BY id DESC LIMIT 10").all(placement);res.json(rows.map(publicSponsorAd))});
app.post('/api/sponsors/:id/view',(req,res)=>{const id=Number(req.params.id);if(Number.isInteger(id)&&id>0)db.prepare("UPDATE sponsor_ads SET views=views+1 WHERE id=? AND active=1 AND datetime(start_at)<=datetime('now') AND datetime(end_at)>=datetime('now')").run(id);res.status(204).end()});
app.post('/api/sponsors/:id/click',(req,res)=>{const id=Number(req.params.id);if(Number.isInteger(id)&&id>0)db.prepare("UPDATE sponsor_ads SET clicks=clicks+1 WHERE id=? AND active=1 AND datetime(start_at)<=datetime('now') AND datetime(end_at)>=datetime('now')").run(id);res.status(204).end()});
app.get('/api/admin/sponsors',requireAdmin,allowPermission('ads.manage'),(req,res)=>res.json(db.prepare("SELECT *,CASE WHEN active=1 AND datetime(start_at)<=datetime('now') AND datetime(end_at)>=datetime('now') THEN 1 ELSE 0 END live FROM sponsor_ads ORDER BY id DESC").all()));
app.post('/api/admin/sponsors',requireAdmin,requireCsrf,allowPermission('ads.manage'),(req,res)=>{const v=sponsorAdSchema.safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid sponsor data'});const x=v.data;const info=db.prepare('INSERT INTO sponsor_ads(company_name,title,description,image,cta_label,cta_url,whatsapp,placement,start_at,end_at,active,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(x.company_name,x.title,x.description,x.image,x.cta_label,x.cta_url,x.whatsapp,x.placement,x.start_at,x.end_at,x.active?1:0,req.admin.sub);audit(req,'SPONSOR_AD_CREATED',String(info.lastInsertRowid),{company:x.company_name,placement:x.placement});res.status(201).json({ok:true,id:info.lastInsertRowid})});
app.patch('/api/admin/sponsors/:id',requireAdmin,requireCsrf,allowPermission('ads.manage'),(req,res)=>{const id=Number(req.params.id);const old=db.prepare('SELECT * FROM sponsor_ads WHERE id=?').get(id);if(!old)return res.status(404).json({error:'Sponsor ad not found'});const v=sponsorAdSchema.partial().safeParse(req.body);if(!v.success)return res.status(400).json({error:'Invalid sponsor data'});const x={...old,...v.data};if(new Date(x.end_at)<=new Date(x.start_at))return res.status(400).json({error:'End must be after start'});db.prepare('UPDATE sponsor_ads SET company_name=?,title=?,description=?,image=?,cta_label=?,cta_url=?,whatsapp=?,placement=?,start_at=?,end_at=?,active=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(x.company_name,x.title,x.description,x.image,x.cta_label,x.cta_url,x.whatsapp,x.placement,x.start_at,x.end_at,x.active?1:0,id);audit(req,'SPONSOR_AD_UPDATED',String(id),{company:x.company_name,placement:x.placement,active:!!x.active});res.json({ok:true})});
app.delete('/api/admin/sponsors/:id',requireAdmin,requireCsrf,allowPermission('ads.manage'),(req,res)=>{const id=Number(req.params.id);const row=db.prepare('SELECT company_name FROM sponsor_ads WHERE id=?').get(id);if(!row)return res.status(404).json({error:'Sponsor ad not found'});db.prepare('DELETE FROM sponsor_ads WHERE id=?').run(id);audit(req,'SPONSOR_AD_DELETED',String(id),{company:row.company_name});res.status(204).end()});
app.get('/api/welcome-discount/eligibility',(req,res)=>{const phone=normalizeCustomerPhone(req.query.phone);if(phone.length<7)return res.status(400).json({error:'Phone required'});const claim=db.prepare('SELECT status,order_id FROM welcome_discount_claims WHERE phone=?').get(phone);const previous=db.prepare("SELECT id FROM orders WHERE phone=? AND status NOT IN ('CANCELLED','PAYMENT_ERROR') LIMIT 1").get(phone);res.json({eligible:!claim&&!previous,percent:20,code:'WELCOME20'});});
app.post('/api/orders/fib',optionalCustomer,async(req,res)=>{const s=orderSchema.safeParse(req.body);if(!s.success)return res.status(400).json({error:'Invalid order'});const subtotalUsd=s.data.items.reduce((n,i)=>n+i.qty*i.priceUsd,0);if(subtotalUsd<=0)return res.status(400).json({error:'Price required'});const phone=normalizeCustomerPhone(s.data.customer.phone);const id='DEVA-'+crypto.randomInt(100000,999999);let discountUsd=0,discountCode=null;
try{db.transaction(()=>{if(s.data.welcomeDiscount){const claim=db.prepare('SELECT 1 FROM welcome_discount_claims WHERE phone=?').get(phone);const previous=db.prepare("SELECT 1 FROM orders WHERE phone=? AND status NOT IN ('CANCELLED','PAYMENT_ERROR') LIMIT 1").get(phone);if(!claim&&!previous){discountUsd=Math.round(subtotalUsd*20)/100;discountCode='WELCOME20';db.prepare("INSERT INTO welcome_discount_claims(phone,order_id,status) VALUES(?,?,'RESERVED')").run(phone,id);}}const totalUsd=Math.max(0,Math.round((subtotalUsd-discountUsd)*100)/100);const totalIqd=Math.round(totalUsd*Number(process.env.IQD_PER_USD||1310));db.prepare('INSERT INTO orders(id,customer_name,phone,email,subtotal_usd,discount_usd,discount_code,total_usd,total_iqd,items_json,customer_id) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(id,s.data.customer.name,phone,s.data.customer.email||null,subtotalUsd,discountUsd,discountCode,totalUsd,totalIqd,JSON.stringify(s.data.items),req.customer?.id||null);})();}catch(e){return res.status(409).json({error:'Could not reserve welcome discount'});}
const row=db.prepare('SELECT total_usd,total_iqd,discount_usd,discount_code FROM orders WHERE id=?').get(id);try{const p=await createFibPayment({amountIqd:row.total_iqd,orderId:id});db.prepare('UPDATE orders SET payment_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(p.paymentId,id);res.status(201).json({orderId:id,subtotalUsd,discountUsd:row.discount_usd,discountCode:row.discount_code,totalUsd:row.total_usd,amountIqd:row.total_iqd,...p})}catch(e){db.transaction(()=>{db.prepare("UPDATE orders SET status='PAYMENT_ERROR',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(id);if(discountCode)db.prepare("DELETE FROM welcome_discount_claims WHERE order_id=? AND status='RESERVED'").run(id);})();res.status(503).json({error:e.message,orderId:id})}});
app.get('/api/orders/:id/payment-status',async(req,res)=>{const o=db.prepare('SELECT id,payment_id,payment_status,status FROM orders WHERE id=?').get(req.params.id);if(!o)return res.status(404).json({error:'Not found'});if(!o.payment_id)return res.json(o);try{const s=await getFibStatus(o.payment_id);db.prepare('UPDATE orders SET payment_status=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(s.status,s.status==='PAID'?'PAID':o.status,o.id);res.json({orderId:o.id,...s})}catch(e){res.status(502).json({error:e.message})}});
app.post('/api/payments/fib/callback',(req,res)=>{const supplied=String(req.headers['x-fib-callback-secret']||'');const expected=String(process.env.FIB_CALLBACK_SECRET||'');if(!supplied||!expected||supplied.length!==expected.length||!crypto.timingSafeEqual(Buffer.from(supplied),Buffer.from(expected)))return res.status(401).end();const s=z.object({id:z.string(),status:z.enum(['PAID','UNPAID','DECLINED'])}).safeParse(req.body);if(!s.success)return res.status(406).end();db.transaction(()=>{db.prepare("UPDATE orders SET payment_status=?,status=CASE WHEN ?='PAID' THEN 'PAID' ELSE status END,updated_at=CURRENT_TIMESTAMP WHERE payment_id=?").run(s.data.status,s.data.status,s.data.id);if(s.data.status==='PAID'){const o=db.prepare('SELECT id FROM orders WHERE payment_id=?').get(s.data.id);if(o)db.prepare("UPDATE welcome_discount_claims SET status='REDEEMED',redeemed_at=CURRENT_TIMESTAMP WHERE order_id=?").run(o.id);}})();res.status(202).end()});
app.get('/api/admin/orders',requireAdmin,(req,res)=>res.json(db.prepare('SELECT * FROM orders ORDER BY created_at DESC LIMIT 500').all()));
app.patch('/api/admin/orders/:id',requireAdmin,requireCsrf,allowPermission('orders.write'),(req,res)=>{const s=z.object({status:z.enum(['PENDING','CONFIRMED','PREPARING','SHIPPED','DELIVERED','CANCELLED','PAID'])}).safeParse(req.body);if(!s.success)return res.status(400).json({error:'Invalid status'});db.prepare('UPDATE orders SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(s.data.status,req.params.id);audit(req,'ORDER_STATUS_CHANGED',req.params.id,{status:s.data.status});res.json({ok:true})});
const BUILD_ID=process.env.RENDER_GIT_COMMIT||process.env.RENDER_SERVICE_ID||String(Date.now());
app.set('etag', false);
app.use((req,res,next)=>{if(/\.(?:html|js|css|webmanifest)$/.test(req.path)||req.path==='/'||req.path==='/sw.js'){res.setHeader('Cache-Control','no-store, no-cache, max-age=0, must-revalidate, proxy-revalidate');res.setHeader('CDN-Cache-Control','no-store');res.setHeader('Pragma','no-cache');res.setHeader('Expires','0');res.setHeader('Surrogate-Control','no-store');res.setHeader('X-DEVA-Build',BUILD_ID)}next()});
