app.get('/',(_req,res)=>{res.setHeader('Cache-Control','no-store, no-cache, max-age=0, must-revalidate, proxy-revalidate');res.setHeader('CDN-Cache-Control','no-store');res.setHeader('X-DEVA-Build',BUILD_ID);res.sendFile(path.join(publicRoot,'index.html'),{lastModified:false,cacheControl:false})});
